for key,title in [('shared_compute_debit_attempts','Shared compute debit attempts'),('admit_callback_attempts','Admission callbacks'),('helper_callback_attempts','Helper callbacks'),('frame_Project_selected','Private-frame projections'),('frame_Project_all_scalar_results','Scalar results from all private-frame projections'),('frame_Project_all_managed_results','Managed results from all private-frame projections'),('frame_Project_composite_child','Composite-child projections'),('frame_static_field_count_calls_including_recursion','Static field-count calls, including recursion'),('frame_static_fields_counted','Static fields traversed for counts'),('action_required_classifications','Action-required classifications'),('needs_move_classifications','Managed-move classifications')]:
 lines.append(f'| {title} | {events.get(key,0):,} |')
